function validate([nums, queries]) {
  if (nums.length < 2 || nums.length > 100000) return 'nums needs 2 to 100000 values.';
  if (nums.some((v) => !Number.isInteger(v) || v < 1 || v > 50000)) return 'Each value of nums is a whole number from 1 to 50000.';
  if (queries.length < 1 || queries.length > 100000) return 'queries needs 1 to 100000 values.';
  const total = nums.length * (nums.length - 1) / 2;
  if (queries.some((q) => !Number.isInteger(q) || q < 0 || q >= total)) return 'Each query is a position from 0 to n * (n - 1) / 2 - 1.';
  return null;
}

