function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 1800 + Math.floor(rand() * 201) : 2 + Math.floor(rand() * 8);
  // A shared factor times a multiplier gives gcds above 1; a quarter of the inputs use plain random values.
  const factors = [1, 2, 3, 4, 6, 8, 12, 30, 210, 2310];
  const plain = rand() < 0.25;
  const top = large ? 50000 : 24;
  const nums = Array.from({ length: n }, () => {
    if (plain) return 1 + Math.floor(rand() * top);
    const factor = factors[Math.floor(rand() * (large ? factors.length : 6))];
    return factor * (1 + Math.floor(rand() * Math.floor(top / factor)));
  });
  if (!large && rand() < 0.1) nums[0] = 50000;
  const total = n * (n - 1) / 2;
  const queries = Array.from({ length: large ? 2000 : 1 + Math.floor(rand() * 6) }, () => Math.floor(rand() * total));
  // The first and last positions of the sorted list are the likeliest off-by-one traps.
  if (rand() < 0.5) queries[0] = rand() < 0.5 ? 0 : total - 1;
  return [nums, queries];
}
